from pathlib import Path
import os, stat, hashlib
root = Path('/work')
for name in ('AGENTS.md','CLAUDE.md'):
    p=root/name
    try:
        st=p.lstat()
        print(name, 'exists_entry=True', 'mode='+oct(stat.S_IMODE(st.st_mode)), 'uid='+str(st.st_uid), 'type=' + ('symlink' if stat.S_ISLNK(st.st_mode) else 'regular' if stat.S_ISREG(st.st_mode) else 'other'))
        if stat.S_ISLNK(st.st_mode): print(' target=', os.readlink(p))
        elif stat.S_ISREG(st.st_mode):
            b=p.read_bytes(); print(' bytes=',len(b),'sha256=',hashlib.sha256(b).hexdigest())
    except FileNotFoundError:
        print(name, 'exists_entry=False')
print('work:', oct(stat.S_IMODE(root.stat().st_mode)), 'uid='+str(root.stat().st_uid), 'euid='+str(os.geteuid()))
